import { stripVTControlCharacters, styleText } from 'node:util';
import logSymbols from 'log-symbols';
import wrapAnsi from 'wrap-ansi';
export function sectionHeader(title) {
    return styleText('bold', `${title}:`);
}
const MIN_WRAP_WIDTH = 40;
const LIST_GLYPHS = new Set(['→', '▸', ...Object.values(logSymbols)].map((glyph) => stripVTControlCharacters(glyph)));
export function wrapLines(lines, width) {
    if (width === undefined)
        return [...lines];
    return lines.flatMap((line) => wrapLine(line, width));
}
export function terminalWidth() {
    return process.stdout.isTTY ? process.stdout.columns : undefined;
}
function wrapLine(line, width) {
    const hang = hangingIndent(line);
    const [prefix, body] = splitAtVisibleColumn(line, hang.length);
    const wrapped = wrapAnsi(body, Math.max(width - hang.length, MIN_WRAP_WIDTH), { trim: false });
    return wrapped
        .split('\n')
        .map((part, index) => (index === 0 ? prefix + part : hang + part.trimStart()).trimEnd());
}
function splitAtVisibleColumn(line, columns) {
    let index = 0;
    let seen = 0;
    while (seen < columns && index < line.length) {
        const escape = styleEscapeLength(line, index);
        if (escape > 0) {
            index += escape;
            continue;
        }
        index += String.fromCodePoint(line.codePointAt(index) ?? 0).length;
        seen += 1;
    }
    return [line.slice(0, index), line.slice(index)];
}
const ESCAPE = 0x1b;
function styleEscapeLength(line, index) {
    if (line.charCodeAt(index) !== ESCAPE || line[index + 1] !== '[')
        return 0;
    const end = line.indexOf('m', index);
    return end === -1 ? 0 : end - index + 1;
}
function hangingIndent(line) {
    const [, spaces = '', glyph] = /^( *)(?:(\S) )?/.exec(stripVTControlCharacters(line)) ?? [];
    const glyphWidth = glyph !== undefined && LIST_GLYPHS.has(glyph) ? 2 : 0;
    return ' '.repeat(spaces.length + glyphWidth);
}
export function pluralize(count, noun) {
    return `${count} ${noun}${count === 1 ? '' : 's'}`;
}
export function formatKeyValue({ key, value, indent = 2, padTo = 0, emphasis, }) {
    const paddedKey = `${key}:`.padEnd(padTo > 0 ? padTo + 1 : key.length + 1);
    const pad = ' '.repeat(indent);
    if (emphasis) {
        return `${pad}${styleText('bold', styleText(emphasis, `${paddedKey} ${value}`))}`;
    }
    return `${pad}${styleText('dim', paddedKey)} ${value}`;
}
export function formatTable(headers, rows) {
    const width = (cell) => stripVTControlCharacters(cell).length;
    const widths = headers.map((header, i) => Math.max(width(header), ...rows.map((row) => width(row[i] ?? ''))));
    const formatRow = (row) => widths
        .map((columnWidth, i) => {
        const cell = row[i] ?? '';
        return cell + ' '.repeat(columnWidth - width(cell));
    })
        .join('   ')
        .trimEnd();
    return [styleText('cyan', formatRow(headers)), ...rows.map(formatRow)];
}
export function clipToLimit(rows, limit) {
    if (rows.length <= limit) {
        return { rows };
    }
    return {
        rows: rows.slice(0, limit),
        note: styleText('dim', `showing the first ${limit} — raise --limit to see more`),
    };
}
export function logClippedTable({ rows, limit, moreAvailable, headers, toCells, log, }) {
    const { rows: clipped, note } = clipToLimit(rows, limit);
    for (const line of formatTable(headers, clipped.map(toCells))) {
        log(line);
    }
    if (note || moreAvailable) {
        log(note ??
            styleText('dim', `searched the first ${limit} candidates — raise --limit to see more`));
    }
}
export function groupBanner({ label, index, total, }) {
    if (total <= 1) {
        return undefined;
    }
    const gap = index > 0 ? '\n' : '';
    return `${gap}${styleText('bold', `▸ ${label}`)}`;
}
export function resourceLabel(resource) {
    return resource.type === 'dataset' ? resource.id : `${resource.type}:${resource.id}`;
}
export function searchedScope(args) {
    const partition = args.partition === undefined ? 'any partition' : `partition ${args.partition}`;
    const deployment = args.deployment === undefined ? '' : ` (deployment ${args.deployment})`;
    return `in ${partition} of ${args.resources.map(resourceLabel).join(', ')}${deployment}`;
}
export const activityIcon = {
    done: logSymbols.success,
    active: styleText('cyan', '●'),
    failed: logSymbols.error,
    skipped: styleText('dim', '⊘'),
};
export function warningLines(warnings) {
    return (warnings ?? []).map((w) => `      ${logSymbols.warning} ${w}`);
}
